INSERT INTO box_graph_node (component_id, shilue_id, shilue_name, box_id, node_key, node_type, name, extra_json) VALUES ('GLBL_00056_REL_HD_COL_010', 'GLBL_00056', '尧', 'GLBL_00056', 'hd_col_010', 'person', '共工', '{"关系ID": "HD-COL-010", "关系类别": "同僚", "关系层级": "二级", "上级连接线标题": "", "关系简述": "尧的大臣，由讙兜推荐。尧认为他言辞漂亮但做事偏邪、表面恭敬实则轻慢上天，拒绝重用。后试用为工师，果然放纵邪僻，被舜流放到北方的幽陵。", "所属一级关系": "同僚", "关系链": "尧 › 同僚", "record_id": "recf51b1f7af98f"}');
