INSERT INTO box_graph_edge (box_id, from_node_key, to_node_key, label) VALUES ('GLBL_00056', 'hd_col_003', 'hd_col_011', '');
INSERT INTO box_graph_node (component_id, shilue_id, shilue_name, box_id, node_key, node_type, name, extra_json) VALUES ('GLBL_00056_REL_HD_COL_012', 'GLBL_00056', '尧', 'GLBL_00056', 'hd_col_012', 'person', '鲧', '{"关系ID": "HD-COL-012", "关系类别": "同僚", "关系层级": "二级", "上级连接线标题": "", "关系简述": "尧的大臣，由四岳力荐负责治水。尧认为他违背天命、毁败同族而反对，但最终听从四岳建议试用。治水九年无功，后被舜在羽山处死。", "所属一级关系": "同僚", "关系链": "尧 › 同僚", "record_id": "rece9bb065e3f44"}');
